contract ChainLinkToken {

    // ============================================================================
    // CONSTANTS
    // ============================================================================

    string public constant name = "ChainLink Token";
    string public constant symbol = "LINK";
    uint8 public constant decimals = 18;
    uint256 public constant totalSupply = 1000000000 * 10**18; // 1 billion tokens

    // ============================================================================
    // STORAGE
    // ============================================================================

    /// @notice Mapping of account addresses to their token balances
    /// @dev Storage slot 1
    mapping(address => uint256) private balances;

    /// @notice Mapping of owner => spender => allowance amount
    /// @dev Storage slot 2
    mapping(address => mapping(address => uint256)) private allowances;

    // ============================================================================
    // EVENTS
    // ============================================================================

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event Transfer(address indexed from, address indexed to, uint256 value, bytes data);

    // ============================================================================
    // VIEW FUNCTIONS
    // ============================================================================

    /// @notice Get the token balance of an account
    /// @param account The address to query
    /// @return The token balance of the account
    function balanceOf(address account) external view returns (uint256) {
        return balances[account];
    }

    /// @notice Get the allowance granted by an owner to a spender
    /// @param owner The address that granted the allowance
    /// @param spender The address that was granted the allowance
    /// @return The remaining allowance amount
    function allowance(address owner, address spender) external view returns (uint256) {
        return allowances[owner][spender];
    }

    // ============================================================================
    // STATE-CHANGING FUNCTIONS
    // ============================================================================

    /// @notice Approve a spender to withdraw up to a specified amount
    /// @param spender The address authorized to spend tokens
    /// @param amount The maximum amount the spender can withdraw
    /// @return Success status
    function approve(address spender, uint256 amount) external returns (bool) {
        require(spender != address(0), "Invalid spender address");
        require(spender != address(this), "Cannot approve to contract itself");

        allowances[msg.sender][spender] = amount;

        emit Approval(msg.sender, spender, amount);

        return true;
    }

    /// @notice Increase the allowance granted to a spender
    /// @param spender The address whose allowance is being increased
    /// @param addedValue The amount to add to the current allowance
    /// @return Success status
    function increaseApproval(address spender, uint256 addedValue) external returns (bool) {
        require(addedValue + allowances[msg.sender][spender] >= allowances[msg.sender][spender], 
                "Allowance overflow");

        allowances[msg.sender][spender] += addedValue;

        emit Approval(msg.sender, spender, allowances[msg.sender][spender]);

        return true;
    }

    /// @notice Decrease the allowance granted to a spender
    /// @param spender The address whose allowance is being decreased
    /// @param subtractedValue The amount to subtract from the current allowance
    /// @return Success status
    function decreaseApproval(address spender, uint256 subtractedValue) external returns (bool) {
        if (subtractedValue <= allowances[msg.sender][spender]) {
            allowances[msg.sender][spender] -= subtractedValue;
        } else {
            allowances[msg.sender][spender] = 0;
        }

        emit Approval(msg.sender, spender, allowances[msg.sender][spender]);

        return true;
    }

    /// @notice Transfer tokens to another account
    /// @param to The recipient address
    /// @param amount The amount of tokens to transfer
    /// @return Success status
    function transfer(address to, uint256 amount) external returns (bool) {
        require(to != address(0), "Invalid recipient address");
        require(to != address(this), "Cannot transfer to contract itself");
        require(amount <= balances[msg.sender], "Insufficient balance");

        balances[msg.sender] -= amount;
        require(balances[to] + amount >= balances[to], "Balance overflow");
        balances[to] += amount;

        emit Transfer(msg.sender, to, amount);

        return true;
    }

    /// @notice Transfer tokens and call a function on the recipient contract
    /// @dev ERC677 extension - calls tokenFallback on recipient if it's a contract
    /// @param to The recipient address
    /// @param value The amount of tokens to transfer
    /// @param data Additional data to pass to the recipient
    /// @return Success status
    function transferAndCall(address to, uint256 value, bytes calldata data) external returns (bool) {
        require(to != address(0), "Invalid recipient address");
        require(to != address(this), "Cannot transfer to contract itself");
        require(value <= balances[msg.sender], "Insufficient balance");

        balances[msg.sender] -= value;
        require(balances[to] + value >= balances[to], "Balance overflow");
        balances[to] += value;

        emit Transfer(msg.sender, to, value);
        emit Transfer(msg.sender, to, value, data);

        // Call tokenFallback on recipient if it's a contract
        if (to.code.length > 0) {
            require(to.code.length > 0, "Recipient is not a contract");

            (bool success, ) = to.call(
                abi.encodeWithSignature(
                    "tokenFallback(address,uint256,bytes)",
                    msg.sender,
                    value,
                    data
                )
            );

            require(success, "tokenFallback call failed");
        }

        return true;
    }

    /// @notice Transfer tokens from one account to another (requires prior approval)
    /// @param sender The address to transfer tokens from
    /// @param recipient The address to transfer tokens to
    /// @param amount The amount of tokens to transfer
    /// @return Success status
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool) {
        require(recipient != address(0), "Invalid recipient address");
        require(recipient != address(this), "Cannot transfer to contract itself");
        require(amount <= balances[sender], "Insufficient balance");

        balances[sender] -= amount;
        require(balances[recipient] + amount >= balances[recipient], "Balance overflow");
        balances[recipient] += amount;

        require(amount <= allowances[sender][msg.sender], "Insufficient allowance");
        allowances[sender][msg.sender] -= amount;

        emit Transfer(sender, recipient, amount);

        return true;
    }

    // ============================================================================
    // FALLBACK FUNCTION
    // ============================================================================

    /// @notice Fallback function - rejects all direct ETH transfers
    receive() external payable {
        revert("Contract does not accept ETH");
    }

    fallback() external payable {
        revert("Contract does not accept ETH");
    }
}
