    }

    /// @notice Returns the implementation address for a specific function selector
    /// @param selector The function selector (bytes4)
    /// @return The implementation address for this selector
    function getImplementationBySelector(bytes4 selector) external view returns (address) {
        return _selectorImplementations[selector];
    }

    /// @notice Returns storage value at a specific slot
    /// @param slot The storage slot
    /// @return The value stored at this slot
    function getStorageValue(uint256 slot) external view returns (uint256) {
