// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/**
 * @title Transparent Proxy Contract
 * @dev Delegates all calls to an implementation contract stored at a fixed storage slot.
 *      This follows the EIP-1967 standard for proxy implementation storage.
 */
contract Proxy {

    // ============================================================================
    // STORAGE
    // ============================================================================

    /// @notice EIP-1967 standard storage slot for implementation address
    /// @dev keccak256("eip1967.proxy.implementation") - 1
    bytes32 private constant IMPLEMENTATION_SLOT = 
        0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

    /// @notice Returns the current implementation address
    function _implementation() internal view returns (address impl) {
        assembly {
            impl := sload(IMPLEMENTATION_SLOT)
        }
    }

    // ============================================================================
    // FALLBACK FUNCTION
    // ============================================================================

    /// @notice Fallback function - delegates all calls to the implementation contract
    /// @dev This is executed when no matching function selector exists in the proxy
    fallback() external payable {
        _delegate(_implementation());
    }

    /// @notice Receive function - accepts plain ETH transfers
    receive() external payable {
        _delegate(_implementation());
    }

    // ============================================================================
    // INTERNAL FUNCTIONS
    // ============================================================================

    /**
     * @dev Delegates the current call to the implementation contract
     * @param implementation Address of the implementation contract
     */
    function _delegate(address implementation) internal virtual {
        assembly {
            // Copy all calldata to memory starting at position 0
            calldatacopy(0, 0, calldatasize())

            // Execute delegatecall to implementation
            // gas(): forward all remaining gas
            // implementation: target contract address
            // 0, calldatasize(): input data location and size in memory
            // 0, 0: output data location and size (will be updated after call)
            let result := delegatecall(
                gas(),
                implementation,
                0,
                calldatasize(),
                0,
                0
            )

            // Copy return data from implementation to memory
            returndatacopy(0, 0, returndatasize())

            // Check if delegatecall succeeded
            if eq(result, 0) {
                // Revert with the return data from failed call
                revert(0, returndatasize())
            }

            // Return the data from successful call
            return(0, returndatasize())
        }
    }
}
```

