        require(!_blacklisted[from], "FiatTokenV2_2: Account is blacklisted");

        _balances[to].value += value;
        require(_balances[to].value >= value, "SafeMath: addition overflow");
        require(_balances[to].value <= type(uint256).max >> 1, 
                "FiatTokenV2_2: Balance exceeds (2^255 - 1)");
        require(!_blacklisted[to], "FiatTokenV2_2: Account is blacklisted");

