        address from,
        address to,
        uint256 value,
        uint256 validAfter,
        uint256 validBefore,
        bytes32 nonce,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external whenNotPaused {
        require(!_blacklisted[from], "Blacklistable: account is blacklisted");
        require(!_blacklisted[to], "Blacklistable: account is blacklisted");
        require(msg.sender == to, "FiatTokenV2: caller must be the payee");
        require(block.timestamp > validAfter, "FiatTokenV2: authorization is not yet valid");
        require(block.timestamp < validBefore, "FiatTokenV2: authorization is expired");
        require(!_authorizationUsed[from][nonce], 
                "FiatTokenV2: authorization is used or cancelled");

        bytes32 digest = keccak256(abi.encodePacked(
            "\x19\x01",
            _domainSeparator,
            keccak256(abi.encode(
                RECEIVE_WITH_AUTHORIZATION_TYPEHASH,
