        require(newMasterMinter != address(0), "FiatToken: new masterMinter is the zero address");
        require(newPauser != address(0), "FiatToken: new pauser is the zero address");
        require(newBlacklister != address(0), "FiatToken: new blacklister is the zero address");
        require(newOwner != address(0), "FiatToken: new owner is the zero address");

        name = tokenName;
        symbol = tokenSymbol;
        currency = tokenCurrency;
        decimals = tokenDecimals;
        masterMinter = newMasterMinter;
        pauser = newPauser;
        blacklister = newBlacklister;
        owner = newOwner;
        _initialized = 1;
    }

    function initializeV2_1(address lostAndFound) external {
        require(_initialized == 1, "Invalid initialization state");

        if (_balances[address(this)].value > 0) {
            require(address(this) != address(0), "ERC20: transfer from the zero address");
            require(lostAndFound != address(0), "ERC20: transfer to the zero address");
            require(_balances[address(this)].value >= _balances[address(this)].value, 
                    "ERC20: transfer amount exceeds balance");

            uint256 contractBalance = _balances[address(this)].value;
            _balances[address(this)].value = 0;

            _balances[lostAndFound].value += contractBalance;
            require(_balances[lostAndFound].value >= contractBalance, 
                    "SafeMath: addition overflow");
            require(_balances[lostAndFound].value <= type(uint256).max >> 1, 
                    "FiatTokenV2_2: Balance exceeds (2^255 - 1)");
            require(!_blacklisted[lostAndFound], "FiatTokenV2_2: Account is blacklisted");

            emit Transfer(address(this), lostAndFound, contractBalance);
        }

        _blacklisted[address(this)] = true;
        _initialized = 2;
    }

    // Internal helper
    function _calculateDomainSeparator() internal view returns (bytes32) {
        return keccak256(abi.encode(
            keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
            keccak256(bytes(name)),
            keccak256("2"),
            block.chainid,
            address(this)
        ));
    }

    // Fallback function
    receive() external payable {
        revert();
    }

    fallback() external payable {
        revert();
    }
}
