    // ========================================================================

    /// @notice Implementation contract address (storage slot 0)
    address public implementation; // stor0

    // ========================================================================
    // FALLBACK FUNCTION
    // ========================================================================

    /// @dev Payable fallback function that handles all unmatched calls
    fallback() external payable {
        // Extract function selector from calldata
        bytes4 selector = msg.sig;

        // Special case: Return implementation address for selector 0xa619486e
        if (selector == 0xa619486e) {
            assembly {
                mstore(0x00, sload(0x00))  // Load stor0 into memory
                return(0x00, 0x20)          // Return 32 bytes
            }
        }

        // Delegate all other calls to the implementation contract
        (bool success, bytes memory returnData) = implementation.delegatecall(
            msg.data
        );

        // Handle delegate call result
        if (!success) {
            // Revert with the error data from the delegate call
            assembly {
                revert(add(returnData, 0x20), mload(returnData))
            }
        }

        // Return the successful delegate call result
        assembly {
            return(add(returnData, 0x20), mload(returnData))
        }
    }

    // ========================================================================
    // RECEIVE FUNCTION (for pure ETH transfers)
    // ========================================================================

    receive() external payable {
        // Delegate to implementation
        (bool success, bytes memory returnData) = implementation.delegatecall(
            msg.data
        );

        if (!success) {
            assembly {
                revert(add(returnData, 0x20), mload(returnData))
            }
        }

        assembly {
            return(add(returnData, 0x20), mload(returnData))
        }
    }
